(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB0RC_1LC1RD_0RB0LC_1RA0RD : Fam := mkFam 2 [[S0;S0;S0];[S1;S0;S0]] [] [[S1]] Binary 1 [mkFill 1 [] 0 [] 0] StC S0 false [S0;S1;S1;S0;S1].
Local Notation FAM := fam_1RB0RC_1LC1RD_0RB0LC_1RA0RD.

(** ** The ladder, as DATA

    3 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB0RC_1LC1RD_0RB0LC_1RA0RD : list (LRule * list rstep) :=
  [(mkLRule (mkC StB (mkS [] [] 0 0 []) S1 (mkS [S0;S0;S1] [] 0 0 [])) (mkC StB (mkS [S1;S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 3, [RB (SWin 3)]);
   (mkLRule (mkC StC (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S0] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S1;S0] [] 0 0 [])) (mkC StD (mkS [S1;S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 [])) 0 3, [RB (SWin 3)])].
Local Notation lad := lad_1RB0RC_1LC1RD_0RB0LC_1RA0RD.

Definition rules_1RB0RC_1LC1RD_0RB0LC_1RA0RD : list LRule := map fst lad.
Local Notation rules := rules_1RB0RC_1LC1RD_0RB0LC_1RA0RD.

Lemma ladder_ok_1RB0RC_1LC1RD_0RB0LC_1RA0RD : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB0RC_1LC1RD_0RB0LC_1RA0RD : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB0RC_1LC1RD_0RB0LC_1RA0RD. Qed.

