(** The boot, on the ORIGINAL machine and up to [lift]: the member at index
    18, past the last fire of every pinned instruction. *)
Lemma bootq_1RB0RC_1RC1LD_1LD0RA_1LB0LD :
  stepn tm_1RB0RC_1RC1LD_1LD0RA_1LB0LD 18 InitES = Some (lift (fam_cfg FAM ([1], 0, 0))).
