          (mkC StD (mkS [S0;S0] [S0;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 [])) 4 8.
Definition ch_iarm0_1_1RB0RD_0RC1RD_1LA1LC_0LC0RD : list rstep := [RB (SWin 2);RB (SCycL 2 0);RB (SWin 4);RB (SCycR 2);RB (SWin 2)].
Lemma ok_iarm0_1_1RB0RD_0RC1RD_1LA1LC_0LC0RD :
