(** The boot, on the ORIGINAL machine and up to [lift]: the member at index
    5, past the last fire of every pinned instruction. *)
Lemma bootq_1RB0RD_0RC1RD_1LA1LC_0LC0RD :
  stepn tm_1RB0RD_0RC1RD_1LA1LC_0LC0RD 5 InitES = Some (lift (fam_cfg FAM ([1], 0, 0))).
Proof.
  assert (H : match csteps tm_1RB0RD_0RC1RD_1LA1LC_0LC0RD 5 c0 with
              | Some c => ceqb c (fam_cfg FAM ([1], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm_1RB0RD_0RC1RD_1LA1LC_0LC0RD 5 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** a pinned instruction fired before the boot: the quasihalt witness *)
Lemma wit_1RB0RD_0RC1RD_1LA1LC_0LC0RD :
  existsb (fun tg => cfires tm_1RB0RD_0RC1RD_1LA1LC_0LC0RD c0 5 tg) pins_1RB0RD_0RC1RD_1LA1LC_0LC0RD = true.
Proof. vm_compute. reflexivity. Qed.

