(** The machine-level theorem, on the QUASIHALTING side: the board above
    runs on the machine wrapped at the pins from the boot member on, and
    [LadderCheckQHTr.boardph_qhtr] closes it. *)
Theorem qhtr_1RB0RD_0RC1RD_1LA1LC_0LC0RD :
  NonHalt tm_1RB0RD_0RC1RD_1LA1LC_0LC0RD /\ QHBoundTr 32779478 tm_1RB0RD_0RC1RD_1LA1LC_0LC0RD /\ QuasiHaltsTr tm_1RB0RD_0RC1RD_1LA1LC_0LC0RD.
Proof.
  apply (boardph_qhtr tm_1RB0RD_0RC1RD_1LA1LC_0LC0RD pins_1RB0RD_0RC1RD_1LA1LC_0LC0RD FAM 2
                      iarm_1RB0RD_0RC1RD_1LA1LC_0LC0RD 1 1
                      farm_1RB0RD_0RC1RD_1LA1LC_0LC0RD 1 1
                      fm1_1RB0RD_0RC1RD_1LA1LC_0LC0RD fm2_1RB0RD_0RC1RD_1LA1LC_0LC0RD 1 vis_1RB0RD_0RC1RD_1LA1LC_0LC0RD
                      [1] 0 5 32779478).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 1; vm_compute; reflexivity. }
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB0RD_0RC1RD_1LA1LC_0LC0RD.
  - repeat constructor.
