  destruct (csteps tm_1RB0RD_1RC0LC_1LD1RA_0RC0LD 47 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

