Lemma iarm_cb_1RB0RD_1RC0RB_1LD1RA_0RC0LD : forall d r,
  d < fm_b FAM - 1 -> r < 1 + 1 -> 0 < lr_cb (iarm_1RB0RD_1RC0RB_1LD1RA_0RC0LD d r).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
    destruct r as [|r].
    { vm_compute; lia. }
