    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB0RD_1RC1RB_1LD1RA_0RC0LD | exact ok_iarm0_0_1RB0RD_1RC1RB_1LD1RA_0RC0LD]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB0RD_1RC1RB_1LD1RA_0RC0LD | exact ok_iarm0_1_1RB0RD_1RC1RB_1LD1RA_0RC0LD]. }
    exfalso; lia.
