Theorem qhtr_1RB0RD_1RC1RB_1LD1RA_0RC0LD :
  NonHalt tm_1RB0RD_1RC1RB_1LD1RA_0RC0LD /\ QHBoundTr 32779478 tm_1RB0RD_1RC1RB_1LD1RA_0RC0LD /\ QuasiHaltsTr tm_1RB0RD_1RC1RB_1LD1RA_0RC0LD.
