  apply (boardph_qhtr tm_1RB0RD_1RC1RB_1LD1RA_0RC0LD pins_1RB0RD_1RC1RB_1LD1RA_0RC0LD FAM 1
                      iarm_1RB0RD_1RC1RB_1LD1RA_0RC0LD 1 1
                      farm_1RB0RD_1RC1RB_1LD1RA_0RC0LD 1 1
                      fm1_1RB0RD_1RC1RB_1LD1RA_0RC0LD fm2_1RB0RD_1RC1RB_1LD1RA_0RC0LD 0 vis_1RB0RD_1RC1RB_1LD1RA_0RC0LD
                      [0] 0 45 32779478).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
