    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB0RD_1RC1RB_1LD1RA_0RC0LD.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
