    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1LA_0LA0RC_0RD0RC_1LD1LB | exact ok_iarm0_1_1RB1LA_0LA0RC_0RD0RC_1LD1LB]. }
    destruct r as [|r].
