  | _, _ => farm1_0_1RB1LA_1LC0LC_1RD1LB_1LA0RD  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB1LA_1LC0LC_1RD1LB_1LA0RD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | _, _ => 0 end.
Definition fm2_1RB1LA_1LC0LC_1RD1LB_1LA0RD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
