  | 0, 1 => iarm0_1_1RB1LB_0LB1RC_0LD0RC_1LA1LD
  | _, _ => iarm0_0_1RB1LB_0LB1RC_0LD0RC_1LA1LD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

