(** The machine-level theorem, on the QUASIHALTING side: the board above
    runs on the machine wrapped at the pins from the boot member on, and
    [LadderCheckQHTr.boardph_qhtr] closes it. *)
Theorem qhtr_1RB1LB_0LB1RC_0LD0RC_1LA1LD :
  NonHalt tm_1RB1LB_0LB1RC_0LD0RC_1LA1LD /\ QHBoundTr 32779478 tm_1RB1LB_0LB1RC_0LD0RC_1LA1LD /\ QuasiHaltsTr tm_1RB1LB_0LB1RC_0LD0RC_1LA1LD.
