  apply (boardph_qhtr tm_1RB1LB_0LB1RC_0LD0RC_1LA1LD pins_1RB1LB_0LB1RC_0LD0RC_1LA1LD FAM 2
                      iarm_1RB1LB_0LB1RC_0LD0RC_1LA1LD 1 1
                      farm_1RB1LB_0LB1RC_0LD0RC_1LA1LD 1 1
                      fm1_1RB1LB_0LB1RC_0LD0RC_1LA1LD fm2_1RB1LB_0LB1RC_0LD0RC_1LA1LD 1 vis_1RB1LB_0LB1RC_0LD0RC_1LA1LD
                      [0] 0 15 32779478).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
