    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 1; vm_compute; reflexivity. }
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB1LB_0LB1RC_0LD0RC_1LA1LD.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - exact bootq_1RB1LB_0LB1RC_0LD0RC_1LA1LD.
